#!/usr/bin/env python3
"""Generate the bilingual introduction site independently of installer readiness."""
import hashlib,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent; SITE=ROOT/'website'
status=json.loads((SITE/'release-status.json').read_text())
site_url=status['websiteURL'].rstrip('/')+'/'
repository=status['sourceRepository']
if status['publicReady']:
    raise SystemExit('Public site rendering requires P15 verified artifact promotion; preview generator cannot enable downloads')

def page(lang,name,title,body):
    en=lang=='en'; base='../' if en else '';home='index.html';other='../'+name+'.html' if en else 'en/'+name+'.html'
    guide='Guide' if en else 'Hướng dẫn';notes='Release notes' if en else 'Ghi chú phiên bản';skip='Skip to content' if en else 'Đến nội dung chính'
    foot=[('guide','Guide' if en else 'Hướng dẫn'),('privacy','Privacy' if en else 'Riêng tư'),('support','Support & terms' if en else 'Hỗ trợ & điều kiện'),('notices','Notices' if en else 'Thành phần')]
    text=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} — PhotoAxis</title><meta name="description" content="{'Native macOS image editor with editable perspective crop. Release in preparation.' if en else 'Chỉnh ảnh native trên macOS, nắn phối cảnh giữ layer chỉnh sửa được. Đang chuẩn bị phát hành.'}"><meta name="robots" content="noindex,nofollow"><meta name="color-scheme" content="dark"><link rel="icon" href="{base}assets/photoaxis-icon.png"><link rel="stylesheet" href="{base}styles.css"></head><body><a class="skip" href="#main">{skip}</a><header><div class="container"><nav aria-label="{'Main' if en else 'Chính'}"><a class="brand" href="{home}"><img src="{base}assets/photoaxis-icon.png" alt="" width="44" height="44">PhotoAxis</a><div class="navlinks"><a href="guide.html">{guide}</a><a href="release-notes.html">{notes}</a><a href="{other}" lang="{'vi' if en else 'en'}" hreflang="{'vi' if en else 'en'}">{'Tiếng Việt' if en else 'English'}</a></div></nav></div></header>{body}<footer><div class="container"><div class="footerlinks">{''.join(f'<a href="{path}.html">{label}</a>' for path,label in foot)}</div><p>{'PhotoAxis 1.0.0 · Apple Silicon · Release in preparation. This local preview has no public installer.' if en else 'PhotoAxis 1.0.0 · Apple Silicon · Đang chuẩn bị phát hành. Preview này chưa có bộ cài public.'}</p></div></footer></body></html>'''
    path=('en/' if en else '')+name+'.html'
    metadata=f'<link rel="canonical" href="{site_url}{path}"><link rel="alternate" hreflang="vi" href="{site_url}{name}.html"><link rel="alternate" hreflang="en" href="{site_url}en/{name}.html">'
    text=text.replace('</head>',metadata+'</head>')
    source_label='Source code' if en else 'Mã nguồn'
    text=text.replace('<a href="guide.html">'+guide+'</a>',f'<a href="{repository}">{source_label}</a><a href="guide.html">{guide}</a>')
    text=text.replace('This local preview has no public installer.','GPLv3 source available. Public installer in preparation.').replace('Preview này chưa có bộ cài public.','Mã nguồn GPLv3 đã công khai. Bộ cài public đang chuẩn bị.')
    folder=SITE/'en' if en else SITE;folder.mkdir(exist_ok=True);(folder/(name+'.html')).write_text(text)

def prose(lang,name,title,body):page(lang,name,title,f'<main id="main" class="container prose"><p class="eyebrow">PhotoAxis 1.0.0</p><h1>{title}</h1>{body}</main>')

for lang in ['vi','en']:
    en=lang=='en';a='../assets/' if en else 'assets/';nativeSuffix='-en' if en else ''
    title='Edit images. Keep your layers.' if en else 'Chỉnh ảnh. Giữ layer để sửa tiếp.'
    lead='A native macOS editor for images, text and shapes. Correct perspective across the document, save an editable project, and export PNG or JPEG.' if en else 'Trình chỉnh ảnh native trên macOS với layer ảnh, chữ và hình. Nắn phối cảnh toàn tài liệu, lưu dự án để sửa tiếp và xuất PNG hoặc JPEG.'
    features=[('Editable perspective','Apply the same perspective correction to images, text and shapes. Existing layers keep their type; new text uses the corrected canvas.'),('Projects and exports','Save layers and embedded sources in one .paxis file. Export the visible result as sRGB PNG or JPEG.'),('Work offline','No account, cloud sync, telemetry or external AI service in the app. Your projects stay in the locations you choose.')] if en else [('Nắn phối cảnh giữ layer','Ảnh, chữ và hình cùng được nắn theo một phép chiếu. Layer cũ vẫn giữ loại nội dung; chữ mới dùng canvas đã nắn.'),('Dự án và ảnh xuất','Lưu layer cùng nguồn nhúng trong một file .paxis. Xuất kết quả hiển thị thành PNG hoặc JPEG sRGB.'),('Làm việc offline','App không có tài khoản, đồng bộ cloud, telemetry hay dịch vụ AI bên ngoài. Dự án nằm ở vị trí bạn chọn lưu.')]
    body=f'''<main id="main" class="container"><section class="hero"><div><p class="eyebrow">{'Native macOS image editor' if en else 'Chỉnh ảnh native trên macOS'}</p><h1>{title}</h1><p class="lead">{lead}</p><div class="tags"><span>Apple Silicon</span><span>macOS 14+</span><span>Tiếng Việt / English</span></div><button class="download" disabled aria-describedby="download-note">{'Release in preparation — 1.0.0 arm64' if en else 'Đang chuẩn bị phát hành — 1.0.0 arm64'}</button><p class="download-note" id="download-note">{'Source is available under GPLv3. Build with Xcode, or wait for the signed installer after acceptance.' if en else 'Mã nguồn đã có giấy phép GPLv3. Bạn có thể tự build bằng Xcode hoặc chờ bộ cài đã ký sau nghiệm thu.'}</p></div><div class="hero-visual"><img src="{a}photoaxis-icon.png" alt="" width="170" height="170"><strong>PhotoAxis</strong><p>.paxis · PNG · JPEG<br>{'Editable layers · offline' if en else 'Layer chỉnh sửa được · offline'}</p></div></section><section class="section"><h2>{'Built for focused editing' if en else 'Các chức năng đã triển khai'}</h2><p class="notice">{'This is a development preview. Native Perspective Crop, Save/Open, Export and recovery have been exercised. Full acceptance, Vietnamese input methods and target machines remain under verification.' if en else 'Đây là preview bản phát triển. Đã kiểm tra native Perspective Crop, Save/Open, Export và recovery; nghiệm thu đầy đủ, bộ gõ tiếng Việt và máy đích còn đang kiểm chứng.'}</p><div class="grid">{''.join(f'<article class="card"><h3>{x}</h3><p>{y}</p></article>' for x,y in features)}</div></section><section class="section"><h2>{'Perspective in the native workspace' if en else 'Phối cảnh trong workspace native'}</h2><div class="pair"><figure><img src="{a}perspective-before-native{nativeSuffix}.png" alt="{'Native English workspace showing a four-corner perspective selection' if en else 'Workspace native tiếng Việt với tứ giác chọn vùng phối cảnh'}" loading="lazy"><figcaption>{'Before Apply · native local Release capture, 2 October 2026.' if en else 'Trước Apply · ảnh chụp native bản Release local, 02/10/2026.'}</figcaption></figure><figure><img src="{a}perspective-after-native{nativeSuffix}.png" alt="{'Native workspace after perspective crop, with editable layers' if en else 'Workspace native sau crop phối cảnh, các layer vẫn chỉnh sửa được'}" loading="lazy"><figcaption>{'After Apply · the same local Release with editable image, text and shape layers.' if en else 'Sau Apply · cùng bản Release local, giữ lớp ảnh, chữ và hình chỉnh sửa được.'}</figcaption></figure></div><p><small>{'Captured from the historical baseline build1 Release after the progress display fix. The app is ad-hoc signed for local QA; these captures do not certify a public installer.' if en else 'Ảnh lịch sử từ Release build 1 sau sửa dòng tiến trình. App ký ad-hoc để QA trên máy; ảnh không thay nghiệm thu bộ cài public.'}</small></p></section><section class="section"><h2>{'Continue after saving' if en else 'Lưu để tiếp tục chỉnh sửa'}</h2><p>{'Save .paxis to preserve editable layers and embedded sources. Export PNG/JPEG when you need a flattened image to share. Recovery contains completed edits; apply an active tool session before relying on it.' if en else 'Save .paxis để giữ layer và nguồn nhúng. Export PNG/JPEG khi cần ảnh phẳng để chia sẻ. Recovery lưu các thay đổi đã chốt; hãy Apply phiên công cụ đang làm trước khi dựa vào recovery.'}</p><a href="guide.html">{'Read the guide' if en else 'Đọc hướng dẫn sử dụng'} →</a></section><section class="section"><h2>{'Limits and scope' if en else 'Giới hạn và phạm vi'}</h2><p>{'Up to 8000 px per edge, 40 MP canvas/source, 50 layers, 120 MP of unique sources per document and 5 tabs. History is limited to 100 steps/128 MiB per document and is not restored after reopening. No PSD/RAW, masks or AI.' if en else 'Tối đa 8000 px mỗi cạnh, 40 MP canvas/mỗi nguồn, 50 layer, 120 MP nguồn duy nhất mỗi tài liệu và 5 tab. History tối đa 100 bước/128 MiB mỗi tài liệu, không khôi phục sau khi mở lại. Chưa hỗ trợ PSD/RAW, mask hay AI.'}</p></section></main>'''
    extra=f'<section class="section"><h2>{"Recovery and rendered output" if en else "Bản phục hồi và ảnh xuất"}</h2><div class="pair"><figure><img src="{a}recovery-native{nativeSuffix}.png" alt="{"Native English startup recovery list with recover and discard controls" if en else "Danh sách phục hồi native tiếng Việt với nút mở và bỏ bản"}" loading="lazy"><figcaption>{"Actual native startup after a controlled QA stop, using a completed timer snapshot. Capture from the historical baseline build1 Release after the progress display fix." if en else "Startup native thực sau dừng bất thường bản QA, dùng snapshot timer đã hoàn tất. Ảnh lịch sử từ Release build 1 sau sửa dòng tiến trình."}</figcaption></figure><figure><img src="{a}mixed-after-render.png" alt="{"Actual PNG output of a synthetic mixed-layer perspective workflow" if en else "PNG xuất thực từ luồng phối cảnh nhiều layer dùng fixture tự tạo"}" loading="lazy"><figcaption>{"Actual P12 PNG export after Save/reopen and continued editing; image output, not a UI screenshot." if en else "PNG xuất thực P12 sau Save/mở lại và sửa tiếp; đây là ảnh đầu ra, không phải screenshot UI."}</figcaption></figure></div></section>'
    investigation_title='Review images with a traceable workflow' if en else 'Rà soát ảnh cùng hồ sơ nguồn'
    investigation_cards=[('Originals and case records','Preserve intake bytes and SHA-256 separately from working copies. Review metadata, annotate, compare and export reviewed PNG/A4-PDF copies.'),('Vietnamese OCR and video frames','Recognize a selected source region locally, keep human confirmations separate, and extract video frames with source hash, frame index and timestamp.'),('Calibrated measurements','Measure distance and area using a recorded reference scale, points and geometry assumptions. Results require a suitable image and calibration.')] if en else [('Nguồn gốc và hồ sơ ảnh','Giữ file tiếp nhận cùng SHA-256 riêng với bản làm việc. Xem metadata, chú thích, so sánh và xuất bản PNG/PDF A4 đã rà soát.'),('OCR tiếng Việt và khung video','Nhận chữ trong vùng nguồn ngay trên máy, giữ bản xác nhận riêng; trích khung video kèm hash nguồn, số khung và mốc thời gian.'),('Đo có hiệu chuẩn','Đo khoảng cách và diện tích với thước chuẩn, điểm đo và giả định hình học được lưu. Kết quả cần ảnh và hiệu chuẩn phù hợp.')]
    investigation=f'<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 3</p><h2>{investigation_title}</h2><div class="grid">'+''.join(f'<article class="card"><h3>{x}</h3><p>{y}</p></article>' for x,y in investigation_cards)+'</div><div class="pair gallery"><figure><img src="'+a+'ocr-native'+nativeSuffix+'.png" alt="'+('Native OCR review with original Vietnamese text and a separate confirmation' if en else 'Rà soát OCR native, chữ tiếng Việt nguồn và bản xác nhận riêng')+'" loading="lazy"><figcaption>'+('Actual build 3 capture: local Vietnamese OCR and source review.' if en else 'Ảnh native build 3: OCR tiếng Việt local và đối chiếu vùng nguồn.')+'</figcaption></figure><figure><img src="'+a+'measurement-native-vi.png" alt="'+('Native Vietnamese measurement panel with reference scale and recorded points' if en else 'Bảng đo native với thước chuẩn và các điểm đã ghi')+'" loading="lazy"><figcaption>'+('Actual Vietnamese build 3 capture: a synthetic calibration fixture, not a real evidence measurement.' if en else 'Ảnh native build 3: fixture thước chuẩn tự tạo, không phải số đo vật chứng thực.')+'</figcaption></figure></div><p class="notice">'+('Hashes check integrity; they do not certify origin, authenticity or capture time. OCR, decoded frames and measurements need human review and suitable source data.' if en else 'Hash kiểm toàn vẹn, không chứng nhận nguồn gốc, tính xác thực hay thời gian chụp. OCR, khung giải mã và số đo cần người rà soát cùng dữ liệu nguồn phù hợp.')+'</p></section>'
    scan_title = 'Clean and standardize document scans' if en else 'Làm sạch và chuẩn hóa bản scan'
    scan_text = ('Detect page corners and text angle; whiten paper, reduce shadows/noise and use adaptive black and white. Manual two-axis page-bow correction and A4/Letter/custom size. Batch up to 50 images with ordered PNG, editable projects, PDF and a hash manifest. Review every page; real camera/book and maximum-quota qualification is pending.' if en else 'Phát hiện góc trang và hướng dòng chữ; làm trắng giấy, giảm bóng/nhiễu và đen trắng thích nghi. Nắn cong hai trục thủ công, chuẩn hóa A4/Letter/kích thước riêng. Xử lý tối đa50ảnh thành PNG, project editable, PDF và manifest hash theo thứ tự. Cần rà từng trang; ảnh giấy/sách chụp thực và full quota còn nghiệm thu.')
    scan_section = f'<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 4</p><h2>{scan_title}</h2><p>{scan_text}</p><p><a href="{repository}/blob/main/docs/HUONG_DAN_SCAN.md">'+('Scan workflow and limitations' if en else 'Hướng dẫn Scan và giới hạn')+'</a></p></section>'
    integrated = ('<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 5</p><h2>One workspace for editing and analysis</h2><p>Sources, Analysis and Output sit beside Edit in the native sidebar. Case intake, annotations, Vietnamese OCR, video frames, calibrated measurements and reviewed exports share the editor. Comparisons and source review use the canvas; pick regions and ordered points directly on the image, then Apply or Cancel. No separate Investigation menu or window.</p><p><a href="'+repository+'/blob/main/docs/HUONG_DAN_DIEU_TRA.md">Integrated workflow and limitations</a></p></section>' if en else '<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 5</p><h2>Chỉnh sửa và phân tích trong cùng workspace</h2><p>Nguồn, Phân tích và Đầu ra nằm bên cạnh Chỉnh sửa trên sidebar native. Tiếp nhận hồ sơ, chú thích, OCR tiếng Việt, khung video, đo có hiệu chuẩn và xuất đã rà soát dùng chung phần mềm. So sánh và đối chiếu nguồn hiện trên canvas; chọn vùng và điểm trực tiếp trên ảnh rồi Áp dụng hoặc Hủy. Không có menu hay cửa sổ Điều tra riêng.</p><p><a href="'+repository+'/blob/main/docs/HUONG_DAN_DIEU_TRA.md">Hướng dẫn tích hợp và giới hạn</a></p></section>')
    paint_live = ('<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 6</p><h2>Live previews, Brush and Clone Stamp</h2><p>Scan controls refresh the before/after result automatically. Crop and Perspective Crop show a live result inset while you adjust the corners. Image and Canvas Size refresh while typing; image adjustment sliders already preview continuously. Brush (B) draws on an editable paint layer with size, hardness, opacity and foreground color; Clone Stamp (S) samples the visible composite with Option-click and preserves a frozen sample. Aligned and unaligned strokes are supported. Release the pointer to commit one Undo step; Escape cancels the current stroke. Projects with paint use schema4 and include clone samples. Source originals remain intact.</p><p><a href="'+repository+'/blob/main/docs/HUONG_DAN_BRUSH_CLONE.md">Controls, project compatibility and limits</a></p></section>' if en else '<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 6</p><h2>Xem trực tiếp, Brush và Clone Stamp</h2><p>Tham số Scan tự cập nhật kết quả trước/sau. Crop và Perspective Crop hiện ô kết quả trực tiếp khi chỉnh góc. Kích thước ảnh/canvas tự xem trước khi nhập; thanh chỉnh sáng/màu đã xem trước liên tục. Brush (B) vẽ trên layer nét vẽ editable, có cỡ, độ cứng, độ đậm và màu tiền cảnh; Clone Stamp (S) lấy mẫu ảnh tổng hợp bằng Option-click và giữ mẫu cố định. Hỗ trợ giữ độ lệch hoặc lấy lại điểm mẫu mỗi nét. Thả chuột chốt một Undo; Escape hủy nét đang kéo. Project có nét vẽ dùng schema4 và nhúng mẫu clone, nguồn gốc giữ nguyên.</p><p><a href="'+repository+'/blob/main/docs/HUONG_DAN_BRUSH_CLONE.md">Thao tác, tương thích project và giới hạn</a></p></section>')
    ui_refinement = ('<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 7</p><h2>Readable rulers and useful Settings</h2><p>Horizontal and vertical rulers share the canvas origin, use readable horizontal numbers and keep each label inside its bounds. Choose px, mm, cm or inches in Settings; print units follow document PPI. Settings now has General, Workspace, Canvas and Default Brush sections, with saved preferences for panel width, rulers, canvas background, transparency grid and the defaults used by newly opened documents.</p><h2>Investigation in the same workspace</h2><p>The right panel now shows four persistent buttons: Edit, Sources, Analysis and Output. In Sources, create or open a case, intake an image and select its working document. Edit uses the ordinary canvas tools. Analysis contains annotations, OCR, video frames, calibrated measurement and comparison; Output contains review and separate sharing exports. Calibration is needed to measure objects in an image; print ruler units alone are not calibration.</p><p><a href="'+repository+'/blob/main/docs/HUONG_DAN_CAI_DAT.md">Settings guide</a> · <a href="'+repository+'/blob/main/docs/HUONG_DAN_DIEU_TRA.md">Investigation workflow</a></p></section>' if en else '<section class="section"><p class="eyebrow">PhotoAxis 1.0.0 · build 7</p><h2>Thước rõ chữ, Cài đặt đầy đủ hơn</h2><p>Thước ngang và dọc cùng gốc tọa độ canvas, số nằm ngang dễ đọc và giữ trọn trong vùng thước. Chọn px, mm, cm hoặc inch trong Cài đặt; đơn vị in theo PPI của tài liệu. Cài đặt có bốn nhóm Chung, Workspace, Canvas và Cọ mặc định, lưu chiều rộng bảng, thước, nền vùng làm việc, ô trong suốt và thông số cọ cho tài liệu mở mới.</p><h2>Điều tra trong cùng workspace</h2><p>Bảng bên phải luôn hiện bốn nút Chỉnh sửa, Nguồn, Phân tích và Đầu ra. Vào Nguồn để tạo hoặc mở hồ sơ, tiếp nhận ảnh và chọn bản làm việc; Chỉnh sửa dùng các công cụ canvas thông thường. Phân tích có chú thích, OCR, khung video, đo có hiệu chuẩn và đối chiếu. Đầu ra có rà soát và bản chia sẻ riêng. Đo vật trong ảnh cần hiệu chuẩn; đơn vị thước in chưa phải chuẩn đo vật.</p><p><a href="'+repository+'/blob/main/docs/HUONG_DAN_CAI_DAT.md">Hướng dẫn Cài đặt</a> · <a href="'+repository+'/blob/main/docs/HUONG_DAN_DIEU_TRA.md">Quy trình điều tra</a></p></section>')
    extra = ui_refinement + paint_live + integrated + scan_section + investigation + extra
    source_cta=f'<p class="source-cta"><a class="download source-button" href="{repository}">'+('Explore source · GPLv3' if en else 'Xem mã nguồn · GPLv3')+'</a></p>'
    body=body.replace('<button class="download"',source_cta+'<button class="download"')
    body=body.replace('</main>',extra+'</main>')
    page(lang,'index','PhotoAxis',body)
    if not en:
        guide='''<h2>Cài và mở</h2><p>Bộ cài public chưa phát hành. Khi đã có DMG được ký/notarize, tải từ đường dẫn phiên bản kèm checksum, mở DMG và kéo PhotoAxis vào Applications. Mở theo luồng Gatekeeper bình thường; không tắt Gatekeeper hoặc xóa quarantine. Nếu cảnh báo không xác minh được nhà phát triển xuất hiện, dừng và dùng kênh hỗ trợ đã công bố.</p><h2>Ngôn ngữ và tài liệu</h2><p>Cài đặt có Theo hệ thống, Tiếng Việt và English; thay đổi áp dụng lần mở app sau. Số và ngày theo vùng của macOS. Nội dung chữ/tên layer không đổi theo UI. New tạo canvas/preset/nền/PPI; Open nhận PNG/JPEG/HEIC tĩnh hoặc .paxis. File vượt giới hạn có lựa chọn thu nhỏ hoặc hủy, không tự đổi chất lượng.</p><h2>Layer và công cụ</h2><p>Place/drag/paste thêm ảnh theo ngữ cảnh. Chọn một layer; đổi tên/thứ tự/ẩn/khóa/opacity, duplicate/delete. Layer khóa vẫn chọn được nhưng không sửa trực tiếp. Move/Transform có phiên preview; Apply chốt một bước Undo, Cancel bỏ phiên. Crop Free/Ratio/W×H; Image Size/Canvas Size và xoay/lật tác động toàn tài liệu.</p><h2>Perspective Crop</h2><ol><li>Chọn công cụ Perspective Crop, đặt bốn góc TL/TR/BR/BL theo vùng cần giữ; dùng zoom/pan để đặt chính xác.</li><li>Chọn Auto, Ratio hoặc W×H; xem grid/Preview, kiểm kích thước. Tứ giác giao nhau/lõm/gần thẳng hoặc kích thước vượt hạn không Apply được.</li><li>Apply nắn tất cả layer cũ, kể cả layer ẩn/khóa, cùng cập nhật canvas và clip. Không flatten. Undo/Redo khôi phục trạng thái trước/sau.</li><li>Chữ mới sau crop nằm thẳng. Chữ cũ projective sửa qua Properties để giữ ma trận/clip. Nguồn ngoài vùng crop vẫn nhúng trong dự án nhưng bị clip khỏi ảnh xuất.</li></ol><h2>Chữ, hình và màu</h2><p>Type tạo chữ nhiều dòng; Return xuống dòng, Cmd+Return Apply, Escape Cancel. Telex/VNI thực còn nghiệm thu; chưa cam kết bộ gõ ngoài phạm vi kiểm chứng. Rectangle/Ellipse/Line có fill/stroke; chọn màu HEX/RGB hoặc Eyedropper lấy composite không overlay. Font thiếu sẽ fallback và báo tên gốc; dự án giữ tên font, kết quả có thể khác cho tới khi cài hoặc thay font. File font không được nhúng.</p><p>Exposure/Brightness/Contrast/Saturation thuộc layer ảnh; bật/tắt/reset và Undo. Các lần kéo preview chỉ chốt một command; nguồn ảnh không bị ghi đè.</p><h2>Save khác Export</h2><p><strong>Save/Save As .paxis</strong> lưu một ZIP với nguồn ảnh nguyên byte, layer editable, ma trận/clip/thông số và preview. Có thể chuyển file sang thư mục khác mà không cần ảnh nhập gốc. History chỉ trong phiên và không lưu trong dự án; mở lại bắt đầu lịch sử mới.</p><p><strong>Export PNG/JPEG</strong> xuất composite các layer hiển thị ở kích thước/PPI đã chọn, sRGB8-bit. PNG có thể giữ alpha; JPEG luôn matte đục (mặc định trắng) và quality1–100. Export loại GPS/metadata nguồn, không xóa dấu chưa lưu dự án. Save .paxis vẫn giữ nguồn nguyên byte, gồm metadata gốc.</p><h2>Recovery và đóng app</h2><p>Recovery ghi các thay đổi đã Apply theo chu kỳ; tác vụ hoàn tất trong giới hạn được kiểm tra mới là điểm phục hồi, không phải mỗi phím vừa gõ. Phiên crop/text/transform chưa chốt không được hứa phục hồi. Sau dừng bất thường, chọn mở bản phục hồi hoặc bỏ; bản phục hồi mở thành tài liệu chưa lưu để Save As. Save chỉ dọn recovery đúng state đã ghi; Don’t Save dọn tài liệu đã đóng. Cancel giữ các tab và bản phục hồi. Recovery lỗi báo rõ, không đảm bảo bản đang ghi dở dùng được.</p><h2>Giới hạn</h2><p>Apple Silicon/macOS14+ là mục tiêu hỗ trợ; macOS14/màn hình1× còn chờ nghiệm thu. 8000px/cạnh,40MP/canvas và nguồn,50layer,120MP nguồn duy nhất,5tab;100 bước/128MiB History. Normal, một layer được chọn. Không PSD/RAW/Mask/AI/Intel/App Store. Tổ hợp giới hạn không có cam kết tốc độ giống tài liệu cơ bản.</p>'''
        privacy='''<h2>Dữ liệu trong app</h2><p>PhotoAxis xử lý ảnh offline. App không có tài khoản, telemetry, cloud sync, quảng cáo, dịch vụ AI hoặc updater qua máy chủ riêng. Dự án và ảnh xuất lưu ở vị trí bạn chọn; Settings và recovery nằm trong vùng dữ liệu ứng dụng trên máy.</p><h2>Nguồn nhúng và metadata</h2><p>.paxis giữ nguồn ảnh nguyên byte để sửa tiếp, nên có thể chứa EXIF/GPS và nội dung ngoài vùng crop. Crop clip không xóa các byte nguồn khỏi dự án. Chỉ chia sẻ .paxis khi bạn đồng ý chia sẻ toàn bộ nguồn. PNG/JPEG xuất mới loại GPS/metadata nguồn; không coi Export là công cụ chứng nhận ẩn mọi thông tin nhạy cảm nhìn thấy trong ảnh.</p><h2>Recovery</h2><p>Recovery là bản dự án local tự chứa. Save hoặc Don’t Save dọn đúng bản theo vòng đời tài liệu; dữ liệu chưa chốt không được hứa phục hồi. Không đồng bộ recovery lên dịch vụ của PhotoAxis.</p><h2>Website và tải app</h2><p>Preview static này không có analytics, cookie, form tài khoản, CDN font hoặc tracker. Website được lưu trữ trên GitHub Pages; máy chủ GitHub có thể xử lý IP và log truy cập theo <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">chính sách riêng tư của GitHub</a>. Mã nguồn và báo cáo lỗi công khai nằm trên GitHub; không đăng ảnh hoặc dữ liệu hồ sơ nhạy cảm vào issue.</p>'''
        support='''<h2>Hỗ trợ</h2><p>Thông tin nhà phát hành và địa chỉ hỗ trợ chính thức chưa được chủ dự án chốt, sẽ công bố cùng bản phát hành. Hiện chưa có địa chỉ email mẫu hoặc đường dẫn issue giả.</p><p>Khi báo lỗi, ghi version/build, macOS/chip/RAM, thao tác tái hiện và thông báo lỗi. Dùng fixture tự tạo khi có thể; không gửi dự án/ảnh cá nhân, mật khẩu, khóa riêng hoặc token vào báo cáo công khai. .paxis có thể chứa nguồn/GPS nguyên byte.</p><h2>Điều kiện sử dụng</h2><p>License, điều kiện phân phối và giá chưa công bố. Preview không tự cấp phép mã nguồn, không cam kết miễn phí, thương mại hoặc subscription. App không có tài khoản hay subscription service. Bộ cài public chỉ được cung cấp khi các điều kiện này đã được chủ dự án chọn.</p>'''
        notices='''<p>Ứng dụng sử dụng framework hệ thống Apple: AppKit/Foundation, MetalKit/Core Image/Core Graphics/Image I/O/Core Text/ColorSync; zlib hệ thống phục vụ ZIP/CRC. Không nhúng package bên thứ ba hoặc file font.</p><p>Icon PhotoAxis và vector công cụ được tự vẽ bằng mã của dự án. Ảnh demo từ fixture hình học/màu/chữ tự tạo. Ảnh phối cảnh và recovery Việt/Anh là capture native lịch sử từ Release build 1. Không dùng ảnh reference Adobe, logo Photoshop, stock hoặc mockup web làm tài nguyên phân phối.</p><p>Framework Apple theo điều khoản SDK Apple; xem <a href="https://zlib.net/zlib_license.html">giấy phép zlib</a>. Mã nguồn PhotoAxis được cấp phép GNU GPL phiên bản 3 (GPL-3.0-only); xem LICENSE trong repository. Tài nguyên và framework bên ngoài tuân theo điều khoản của chủ sở hữu tương ứng. Công cụ build/test không phải tài nguyên nhúng trong app.</p>'''
        notes='''<p class="notice">Bản 1.0.0 (1) đang chuẩn bị phát hành, chưa có bộ cài public.</p><h2>Đã triển khai trong bản phát triển</h2><ul><li>Workspace native Tiếng Việt/English, nhiều tab, Layers/Move/Transform/History.</li><li>Crop/kích thước/xoay/lật; Perspective Crop toàn tài liệu giữ ảnh/chữ/hình editable và clip.</li><li>Type/Rectangle/Ellipse/Line/Color/Eyedropper; điều chỉnh ảnh theo layer.</li><li>.paxis schema1 tự chứa nguồn; Save/Open an toàn; PNG/JPEG sRGB với alpha/matte/quality/kích thước/PPI.</li><li>Recovery thay đổi đã chốt và preflight đóng/quit nhiều tài liệu.</li></ul><h2>Còn nghiệm thu</h2><p>Bộ gõ Telex/VNI thực, phần native shortcut/bố cục/tác vụ nền còn lại, macOS14/non-Retina/máy chuẩn và cài sạch signed/offline. Hiệu năng worker đã đo trên M1 Pro32GB/macOS27; chưa chứng nhận native FPS hoặc số đo máy khác. Cảnh báo Metal/QoS còn được điều tra. Chi tiết sẽ được chốt trước phát hành.</p><h2>Yêu cầu và giới hạn</h2><p>Mục tiêu Apple Silicon/macOS14+; không Intel/App Store. PSD/RAW/Mask/AI chưa hỗ trợ. History không lưu qua lần mở lại; font không nhúng. Save .paxis giữ nguồn/GPS nguyên byte; Export ảnh loại metadata GPS nguồn.</p>'''
    else:
        guide='''<h2>Install and open</h2><p>The public installer is not released yet. Once a signed, notarized DMG is available, download the versioned asset and checksum, open it and drag PhotoAxis to Applications. Use normal Gatekeeper checks. Do not disable Gatekeeper or remove quarantine. If the developer cannot be verified, stop and contact the published support channel.</p><h2>Language and documents</h2><p>Settings offers System Default, Tiếng Việt and English; changes apply on the next launch. Numbers and dates follow the macOS region. Layer names and text do not change with the interface. New creates a preset/custom canvas with background and PPI. Open accepts static PNG/JPEG/HEIC or .paxis. Oversized inputs require a resize choice or cancellation.</p><h2>Layers and tools</h2><p>Place/drag/paste adds images according to context. Select one layer, rename/reorder/hide/lock/change opacity/duplicate/delete it. A locked layer can be selected but not directly edited. Move/Transform has a preview session: Apply creates one Undo step, Cancel discards the draft. Crop supports Free/Ratio/W×H; Image Size/Canvas Size/rotate/flip operate on the document.</p><h2>Perspective Crop</h2><ol><li>Choose Perspective Crop and place TL/TR/BR/BL around the retained region, using pan/zoom for accuracy.</li><li>Choose Auto, Ratio or W×H; inspect grid/Preview and dimensions. Invalid or oversized quadrilaterals cannot Apply.</li><li>Apply maps every existing layer, including hidden/locked layers, to the corrected canvas and clip. Layer types and source bytes remain editable; Undo/Redo restores the document.</li><li>New text uses the corrected canvas. Edit older projective text through Properties to preserve its mapping and clip. Cropped-out source content remains embedded but is clipped from output.</li></ol><h2>Text, shapes and color</h2><p>Type supports multiple lines: Return adds a line, Cmd+Return applies and Escape cancels. Actual Telex/VNI acceptance is pending. Rectangle/Ellipse/Line have fill/stroke; HEX/RGB and Eyedropper use the image composite without overlays. Missing fonts are substituted with a warning, while the original font name is preserved. The fallback can look different; font files are not embedded.</p><p>Exposure/Brightness/Contrast/Saturation belong to image layers, with enable/reset/Undo. Preview drags commit one command and do not overwrite source images.</p><h2>Save versus Export</h2><p><strong>Save/Save As .paxis</strong> creates a self-contained ZIP with original source bytes, typed layers, matrices/clips/parameters and preview. Moving the project does not require the original input paths. History is session-only and starts empty after reopening.</p><p><strong>Export PNG/JPEG</strong> flattens visible layers as 8-bit sRGB at the chosen size/PPI. PNG can retain alpha; JPEG uses an opaque matte (white by default) and quality1–100. Export removes original GPS/metadata and leaves the project dirty state intact. Saving .paxis keeps original metadata, including GPS.</p><h2>Recovery and closing</h2><p>Recovery periodically stores committed edits. Only a completed recovery write is a recovery point; an uncommitted crop/text/transform draft is not promised. After an abnormal stop, open or discard the available recovery. Recovered documents open unsaved for Save As. Save clears the matching saved state; Don’t Save clears closed documents, while Cancel preserves tabs/recoveries. Failed/incomplete writes are not guaranteed recoverable.</p><h2>Limits</h2><p>Apple Silicon/macOS14+ is the support target; macOS14/1× hardware verification is pending. Limits:8000px/edge,40MP per canvas/source,50layers,120MP unique sources/document,5tabs,100steps/128MiB History. Normal blend, single layer selection. No PSD/RAW/Mask/AI/Intel/App Store. Maximum quota combinations do not promise basic-document performance.</p>'''
        privacy='''<h2>App data</h2><p>PhotoAxis processes images offline, without accounts, telemetry, cloud sync, advertising, AI services or its own automatic updater. Projects and exports stay where you save them. Settings and recovery use local application storage.</p><h2>Embedded sources and metadata</h2><p>.paxis preserves original source bytes, including possible EXIF/GPS and cropped-out content. A crop clip does not remove source bytes from the project. Share a project only when you intend to share all embedded sources. Fresh PNG/JPEG export removes original GPS/metadata; it does not certify that visible sensitive information has been redacted.</p><h2>Recovery</h2><p>Recovery is a local self-contained project. Save and Don’t Save clean matching records according to the document lifecycle. Draft sessions are not promised recoverable. PhotoAxis does not sync recovery to a cloud service.</p><h2>Website and downloads</h2><p>This static preview has no analytics, cookies, account form, font CDN or trackers. This site is hosted on GitHub Pages. GitHub may process IP addresses and access logs under its <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">privacy statement</a>. Source and public issues are hosted on GitHub; do not upload sensitive case data.</p>'''
        support='''<h2>Support</h2><p>The publisher and official support address are awaiting the project owner’s decision and will be published with the release. There is no placeholder email or fake issue link.</p><p>Report version/build, macOS/chip/RAM, reproduction steps and the error message. Prefer synthetic fixtures. Do not send personal images/projects, passwords, private keys or tokens in public reports; .paxis can contain original sources and GPS.</p><h2>Terms</h2><p>The license, distribution terms and price have not been announced. This preview does not license the source or promise free/commercial/subscription terms. The app contains no account/subscription service. A public installer will be offered after the owner chooses the terms.</p>'''
        notices='''<p>The app uses Apple system frameworks: AppKit/Foundation, MetalKit/Core Image/Core Graphics/Image I/O/Core Text/ColorSync and system zlib for ZIP/CRC. No third-party package or font file is bundled.</p><p>PhotoAxis app/tool icons are authored as project code. Demo content uses synthetic geometry/color/text fixtures. Perspective screenshots capture the historical baseline build1 Release in Vietnamese/English; recovery screenshots capture actual native startup from the same historical baseline build1 Release. Adobe reference images, Photoshop logos, stock content and web mockups are excluded from distribution assets.</p><p>Apple frameworks follow Apple SDK terms; see the <a href="https://zlib.net/zlib_license.html">zlib license</a>. PhotoAxis source is licensed under GNU GPL version 3 (GPL-3.0-only); see LICENSE in the repository. External frameworks retain their respective terms. Build/test tools are not bundled in the app.</p>'''
        notes='''<p class="notice">Version1.0.0(1) is in preparation. No public installer is available yet.</p><h2>Implemented in the development build</h2><ul><li>Native Vietnamese/English workspace, tabs, Layers/Move/Transform/History.</li><li>Crop/size/rotate/flip and document-wide editable Perspective Crop for images/text/shapes.</li><li>Type/Rectangle/Ellipse/Line/Color/Eyedropper and per-image adjustments.</li><li>Self-contained .paxis schema1, safe Save/Open and sRGB PNG/JPEG with alpha/matte/quality/size/PPI.</li><li>Committed-edit recovery and multi-document close/quit preflight.</li></ul><h2>Pending acceptance</h2><p>Real Telex/VNI, remaining native shortcut/layout/background-task checks, macOS14/non-Retina/reference machines and clean signed/offline installation remain pending. Worker performance was measured on M1 Pro32GB/macOS27; native FPS and other machines are not certified. Metal/QoS warnings are under investigation. Final details will be settled before publication.</p><h2>Requirements and limitations</h2><p>Target Apple Silicon/macOS14+; no Intel/App Store. No PSD/RAW/Mask/AI. Session-only history; fonts are not embedded. Save preserves original bytes/GPS in .paxis; Export removes source GPS metadata.</p>'''
    extension = ('<h2>Investigation 2 — development build3</h2><p>Case packages preserve intake originals, hashes and a durable processing log. Vietnamese OCR runs locally with source-region review and separate human confirmations. Video frame extraction records exact source hash, track, frame index and PTS; calibrated distance/area preserves the reference and points. This extension is under local verification and does not certify forensic authenticity or complete public acceptance.</p>' if en else '<h2>Investigation 2 — bản phát triển build3</h2><p>Hồ sơ giữ file tiếp nhận, hash và nhật ký bền vững. OCR tiếng Việt chạy local, có vùng nguồn và bản xác nhận riêng. Trích khung hình video lưu hash nguồn, track, số khung và PTS; đo khoảng cách/diện tích giữ thước chuẩn và điểm đo. Phần mở rộng đang kiểm chứng local, không chứng nhận tính xác thực vật chứng hoặc thay nghiệm thu public.</p>')
    source_guide = (f'<h2>Build from source</h2><p>The source, tests and this website share one <a href="{repository}">public repository</a>. License: GNU GPL version 3 (GPL-3.0-only). With an Apple Silicon Mac and Xcode installed, clone the repository, run <code>./scripts/build.sh Release</code>, or open <code>PhotoAxis.xcodeproj</code>. See <a href="{repository}/blob/main/docs/HUONG_DAN_BUILD.md">build instructions</a> for requirements and output paths. Self-built and local ad-hoc builds are not notarized releases.</p>' if en else f'<h2>Tự build từ mã nguồn</h2><p>Mã nguồn, kiểm thử và website cùng nằm trong <a href="{repository}">một repository public</a>, giấy phép GNU GPL phiên bản 3 (GPL-3.0-only). Trên Mac Apple Silicon đã cài Xcode, clone repository rồi chạy <code>./scripts/build.sh Release</code> hoặc mở <code>PhotoAxis.xcodeproj</code>. Xem <a href="{repository}/blob/main/docs/HUONG_DAN_BUILD.md">hướng dẫn build</a> về yêu cầu và vị trí đầu ra. Bản tự build hoặc ký ad-hoc local chưa phải bản phát hành notarized.</p>')
    guide = source_guide + guide
    support = (f'<h2>Report an issue</h2><p>Use <a href="{repository}/issues">GitHub Issues</a> for reproducible bug reports. Include version/build, macOS, chip/RAM and steps. Use synthetic fixtures; never attach personal images, unredacted cases, passwords or tokens to a public issue.</p><h2>License and distribution</h2><p>PhotoAxis source is GNU GPL version 3 (GPL-3.0-only), including the corresponding source for modifications distributed under that license. See <a href="{repository}/blob/main/LICENSE">the complete license</a>. The software is provided without warranty. A signed, notarized installer is still in preparation; no paid plan or subscription service is announced.</p>' if en else f'<h2>Báo lỗi và góp ý</h2><p>Dùng <a href="{repository}/issues">GitHub Issues</a> để báo lỗi có thể tái hiện. Ghi version/build, macOS, chip/RAM và các bước thực hiện. Dùng fixture tự tạo; không đính kèm ảnh cá nhân, hồ sơ chưa che, mật khẩu hoặc token vào issue công khai.</p><h2>Giấy phép và phân phối</h2><p>Mã nguồn PhotoAxis dùng GNU GPL phiên bản 3 (GPL-3.0-only), gồm nghĩa vụ cung cấp mã nguồn tương ứng khi phân phối bản sửa đổi theo giấy phép này. Xem <a href="{repository}/blob/main/LICENSE">toàn văn giấy phép</a>. Phần mềm được cung cấp không có bảo đảm. Bộ cài đã ký/notarize đang chuẩn bị; chưa công bố gói trả phí hoặc dịch vụ subscription.</p>')
    guide += ui_refinement + paint_live + integrated + scan_section + extension
    notes = notes.replace('Version1.0.0(1)', 'Version1.0.0(7)').replace('1.0.0(1)', '1.0.0(7)').replace('1.0.0 (1)', '1.0.0 (7)') + ui_refinement + paint_live + integrated + scan_section + extension
    privacy += ('<h2>Investigation data</h2><p>.paxcase, analysis JSON and processing logs may include unredacted originals, metadata, OCR text, video frames and measurement records. They are not redacted sharing copies. OCR uses Apple Vision locally; it does not reconstruct missing text or use an external AI service. Reviewed PNG/A4-PDF sharing is separate.</p>' if en else '<h2>Dữ liệu điều tra</h2><p>.paxcase, JSON phân tích và nhật ký có thể chứa nguồn, metadata, chữ OCR, khung video và phép đo chưa che. Không xem đây là bản chia sẻ đã che. OCR dùng Apple Vision local, không tái tạo chữ thiếu hoặc dùng dịch vụ AI bên ngoài. Bản chia sẻ PNG/PDF A4 đã rà soát tách riêng.</p>')
    for name,title,body in [('guide','User guide' if en else 'Hướng dẫn sử dụng',guide),('privacy','Privacy' if en else 'Riêng tư',privacy),('support','Support and terms' if en else 'Hỗ trợ và điều kiện',support),('notices','Components and notices' if en else 'Thành phần và ghi nhận',notices),('release-notes','Release notes' if en else 'Ghi chú phiên bản',notes)]:prose(lang,name,title,body)
print('Generated 12 bilingual static preview pages; download remains disabled')
